using System.Windows.Forms;
using System.Reflection;
class Program {
 [STAThread] static void Main() {
  Console.WriteLine("runtime="+System.Runtime.InteropServices.RuntimeInformation.FrameworkDescription);
  Console.WriteLine("winforms="+typeof(Control).Assembly.GetCustomAttribute<AssemblyInformationalVersionAttribute>()?.InformationalVersion);
  (Type t,string[] p)[] cases = [
   (typeof(ComboBox),["DropDownStyle","DropDownHeight","MaxDropDownItems","IntegralHeight","DrawMode","FormattingEnabled"]),
   (typeof(ListBox),["SelectionMode","IntegralHeight","ItemHeight","DrawMode","FormattingEnabled"]),
   (typeof(CheckedListBox),["CheckOnClick","ThreeDCheckBoxes","SelectionMode"]),
   (typeof(ListView),["View","FullRowSelect","MultiSelect","HideSelection","LabelEdit","CheckBoxes","VirtualMode"]),
   (typeof(TreeView),["ShowLines","ShowRootLines","ShowPlusMinus","HideSelection","Sorted","FullRowSelect"]),
   (typeof(ImageList),["ColorDepth","ImageSize","TransparentColor"]),
   (typeof(ColumnHeader),["Width","Text","TextAlign","DisplayIndex"]),
   (typeof(ErrorProvider),["BlinkRate","BlinkStyle","RightToLeft","HasErrors"]),
   (typeof(System.Windows.Forms.Timer),["Interval","Enabled"]),
   (typeof(PropertyGrid),["PropertySort","HelpVisible","ToolbarVisible","CommandsVisibleIfAvailable"]),
   (typeof(BindingSource),["Position","Count","AllowNew","RaiseListChangedEvents"])
  ];
  foreach(var (t,p) in cases) { object? v=null; try{v=Activator.CreateInstance(t);foreach(string n in p) Console.WriteLine($"{t.Name}.{n}={t.GetProperty(n)?.GetValue(v)??"<null>"}");}catch(Exception ex){Console.WriteLine(t.Name+":"+ex.Message);}finally{(v as IDisposable)?.Dispose();}}
 }
}
